export function auditEntry(req: AdminRequest, action: string, now: Date = new Date()): AuditEntry {
  return {
    actor: req.actor,
    action,
    route: req.path,
    method: req.method,
    occurred_at: now.toISOString(),
    request_id: req.headers["x-request-id"] || req.headers["X-Request-Id"],
  };
}

